const C = {
 quietMHzByBand: {'160':null,'80':null,'60':null,'40':null,'30':null,'20':null,'17':null,'15':null,'12':null,'10':null,'6':null},
 clientHandle:null, scanStart:null, step:2, kneeOffset:1, minThreshold:0,
 settleMs:2500, measureMs:4000, minSamples:20, bandDebounceMs:2000,
 timeoutMs:20000, ackTimeoutMs:5000, staleMs:3000, rxFreshMs:6000, maxRunMs:240000,
 maxSpreadDb:2, maxInputDriftDb:1, kneeDropDb:1.5, plateauDb:0.5, quietToleranceMHz:0.000001
