const now=Date.now(),topic=String(msg.topic||''),p=msg.payload;
const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const numeric=v=>(typeof v==='number'||(typeof v==='string'&&v.trim()!==''))&&Number.isFinite(Number(v));
const ok=v=>v!==null&&v!==undefined&&Number(v)===0;
const threshold=v=>Number.isInteger(v)&&v>=0&&v<=100;
const empty=()=>({version:2,state:'IDLE',auto:false,slices:{},pans:{},meters:{},inventory:{},rx:'UNKNOWN',rxAt:0,
 active:null,band:null,candidate:null,lastInventory:0,lastTxSub:0,epoch:0,sequence:0,pending:null,run:null,
 samples:null,result:null,trace:[],reason:'AUTO OFF; monitor only',settingsLoaded:false,settings:{quietMHzByBand:{...C.quietMHzByBand},scanStart:C.scanStart},settingsError:null});
