const out=[],commands=[],saves=[];
const a=()=>s.slices[s.active]||{};
const actualBand=()=>{const b=a().band??s.pans[String(a().pan)]?.band;return b==null?null:String(b);};
const quiet=()=>{const v=s.settings.quietMHzByBand[s.band];return typeof v==='number'&&Number.isFinite(v)&&v>0?v:null;};
const busy=()=>['BAND_CHANGE','WAIT_RX','MEASURE_NOISE','SCAN_AGCT','KNEE_FOUND','APPLY'].includes(s.state);
const scanning=()=>['SCAN_AGCT','KNEE_FOUND','APPLY'].includes(s.state);
const freshMeters=()=>['LEVEL','AGC+'].every(name=>{const m=s.meters[s.active]?.[name];return m&&m.unit==='dBm'&&now-m.at<=C.staleMs;});
