const signature=()=>JSON.stringify(['mode','filter_lo','filter_hi','rxant','rfgain','nr','nr_level','nb','nb_level','wnb','anf','apf'].map(k=>a()[k]??null));
function blockers(){const b=[];if(!s.settingsLoaded||s.settingsError)b.push(s.settingsError||'SETTINGS LOADING');
 if(quiet()===null)b.push('NO QUIET FREQUENCY CONFIGURED');else if(!atQuiet())b.push('TUNE TO CONFIGURED QUIET FREQUENCY');
 if(!freshMeters())b.push('WAITING FOR LIVE LEVEL / AGC+ IN dBm');if(!['slow','med','fast'].includes(a().agc_mode))b.push('AGC MODE OFF OR UNKNOWN');return b;}
function report(reason=s.reason){s.reason=reason;out.push({topic:'au510m/agct/status',payload:JSON.parse(JSON.stringify({
 state:s.state,auto:s.auto,manualRun:Boolean(s.manual),autoAfterRun:s.manual?s.manual.autoBefore:s.auto,reason,activeSlice:s.active,frequencyMHz:a().RF_frequency??null,band:s.band,
 agcThreshold:a().agc_threshold??null,agcMode:a().agc_mode??null,rxTx:s.rx,meters:s.meters[s.active]||{},
 inventory:s.inventory,inventoryError:s.inventoryError??null,measurement:s.result,quietFrequencyMHz:quiet(),
 settings:s.settings,settingsLoaded:s.settingsLoaded,settingsError:s.settingsError,
 scan:{start:s.run?.initial??null,current:s.run?.current??null,knee:s.knee??null,final:s.final??null,phase:s.phase??null,steps:s.trace.length},
 trace:s.trace,blockers:blockers(),at:now}))});}
function move(state,reason){s.state=state;s.since=now;report(reason);}
function finishManual(){if(s.manual){s.auto=s.manual.autoBefore;s.manual=null;}}
function abort(reason){finishManual();s.pending=null;s.samples=null;s.run=null;s.phase=null;move('ERROR',reason+'; no further writes');}
function read(command){commands.push({payload:command,_agctReadEpoch:s.epoch});}
function begin(reason,scanStart=s.settings.scanStart){s.result=null;s.trace=[];s.knee=null;s.final=null;s.pending=null;s.samples=null;s.run={slice:s.active,band:s.band,started:now,scanStart};move('BAND_CHANGE',reason);}
function newWindow(){s.samples={'LEVEL':[],'AGC+':[]};s.windowAt=now;s.phase='MEASURE';}
function stats(){const r={};for(const name of ['LEVEL','AGC+']){const v=(s.samples?.[name]||[]).slice().sort((x,y)=>x-y);if(v.length<C.minSamples)return null;
 r[name]={unit:'dBm',count:v.length,min:v[0],max:v.at(-1),median:v[Math.floor(v.length/2)],spread:v.at(-1)-v[0]};}return r;}
function sendThreshold(value,purpose){
 if(!s.auto||!s.run||!threshold(value)||s.rx!=='RX'||now-s.rxAt>C.rxFreshMs||!freshMeters()||!atQuiet()||!s.settingsLoaded||s.settingsError){abort('WRITE PRECONDITION FAILED');return;}
 const token=++s.sequence,command='slice s '+s.active+' agc_threshold='+value;
 s.pending={token,command,value,purpose,at:now,ack:false,seen:false,previous:Number(a().agc_threshold)};s.phase='ACK';
 commands.push({payload:command,_agctWrite:{token,epoch:s.epoch}});report(purpose==='apply'?'APPLY; waiting for acknowledgement and live threshold':'SCAN_AGCT; waiting for acknowledgement and live threshold');}
function descend(){const next=s.run.current-C.step;if(next<C.minThreshold){abort('NO KNEE FOUND IN SCAN RANGE');return;}sendThreshold(next,'step');}
function validSettings(v){return object(v)&&object(v.quietMHzByBand)&&Object.entries(v.quietMHzByBand).every(([b,q])=>/^[A-Za-z0-9_-]{1,16}$/.test(b)&&b!=='__proto__'&&b!=='constructor'&&(q===null||(typeof q==='number'&&Number.isFinite(q)&&q>0&&q<=100000)))&&(v.scanStart===null||threshold(v.scanStart));}
if(topic==='settings/load'){
 try{const settings=typeof p==='string'?JSON.parse(p):p;if(!validSettings(settings))throw Error('Invalid settings');s.settings={quietMHzByBand:{...C.quietMHzByBand,...settings.quietMHzByBand},scanStart:settings.scanStart};s.settingsLoaded=true;s.settingsError=null;report('SETTINGS LOADED');}
 catch(e){s.settingsLoaded=true;s.settingsError='SETTINGS FILE INVALID';report(s.settingsError);}
}
if(topic==='settings/missing'){s.settingsLoaded=true;s.settingsError=null;report('NO SAVED SETTINGS; frequencies remain unset');}
if(topic==='settings/error'){s.settingsPending=null;s.settingsLoaded=true;s.settingsError='SETTINGS SAVE / LOAD FAILED';if(busy())abort(s.settingsError);else report(s.settingsError);}
if(topic==='settings/saved'){
 if(msg._settingsToken===s.settingsToken){s.settings=s.settingsPending;s.settingsPending=null;s.settingsLoaded=true;s.settingsError=null;report('SETTINGS SAVED');}
}
if(topic==='control/settings'){
 if(busy())report('STOP CALIBRATION BEFORE CHANGING SETTINGS');
 else if(s.settingsPending)report('SETTINGS SAVE ALREADY IN PROGRESS');
 else if(!s.settingsLoaded||!object(p)||!validSettings({quietMHzByBand:{[p.band]:p.quietMHz},scanStart:p.scanStart}))report('INVALID SETTINGS');
 else{
  s.settingsPending={quietMHzByBand:{...s.settings.quietMHzByBand,[p.band]:p.quietMHz},scanStart:p.scanStart};
  s.settingsToken=(s.settingsToken||0)+1;s.settingsError='SETTINGS SAVING';
  saves.push({topic:'settings/saved',payload:JSON.stringify(s.settingsPending,null,2),_settingsToken:s.settingsToken});report('SAVING SETTINGS');
 }
}
if(topic.startsWith('connection/')){const old=s;s=empty();s.epoch=old.epoch+1;s.auto=old.manual?old.manual.autoBefore:old.auto;s.settings=old.settings;s.settingsLoaded=old.settingsLoaded;s.settingsError=old.settingsError;
 s.settingsToken=old.settingsToken;s.settingsPending=old.settingsPending;
 if(['BAND_CHANGE','WAIT_RX','MEASURE_NOISE','SCAN_AGCT','KNEE_FOUND','APPLY'].includes(old.state))abort('RADIO CONNECTION CHANGED');}
if(msg.error && !topic.startsWith('settings/'))abort('RADIO REQUEST ERROR: '+String(msg.error.message||msg.error));
if(msg._agctWrite&&msg.request&&s.pending&&msg._agctWrite.epoch===s.epoch&&msg._agctWrite.token===s.pending.token){if(!ok(msg.status_code))abort('AGC-T COMMAND REJECTED: '+String(msg.status_code));else s.pending.ack=true;}
if(msg._agctReadEpoch===s.epoch&&msg.request){
 if(!ok(msg.status_code)){s.inventoryError=msg.request+': '+String(msg.status_code);if(busy())abort('SUBSCRIPTION / INVENTORY REQUEST FAILED');}
 else if(msg.request==='meter list'&&object(p)){s.inventory={};for(const [id,m] of Object.entries(p))if(/^\d+$/.test(id)&&object(m)&&String(m.src).toUpperCase()==='SLC'&&['LEVEL','AGC+'].includes(String(m.nam).toUpperCase())){
  const name=String(m.nam).toUpperCase();s.inventory['SLC/'+Number(m.num)+'/'+name]={id,unit:m.unit??null};read('sub meter '+id);}s.inventoryError=null;}
}
if(topic==='interlock'&&object(p)&&typeof p.state==='string'){const state=p.state.toUpperCase();s.rx=['RECEIVE','READY'].includes(state)?'RX':state==='TRANSMITTING'?'TX':'UNKNOWN';s.rxAt=now;
 if(busy()&&!['BAND_CHANGE','WAIT_RX'].includes(s.state)&&s.rx!=='RX')abort('RX LOST: '+state);}
const sm=topic.match(/^slice\/(\d+)(\/removed)?$/);
if(sm){const id=String(Number(sm[1]));if(sm[2]||p==='removed'||(object(p)&&Number(p.in_use)===0)){delete s.slices[id];delete s.meters[id];}
 else if(object(p)){s.slices[id]={...(s.slices[id]||{}),...p};if(s.pending&&id===s.active&&numeric(p.agc_threshold)&&Number(p.agc_threshold)===s.pending.value)s.pending.seen=true;}}
const pm=topic.match(/^display\/pan\/([^/]+)$/);if(pm&&object(p))s.pans[pm[1]]={...(s.pans[pm[1]]||{}),...p};
const candidates=Object.entries(s.slices).filter(([,v])=>Number(v.active)===1&&(C.clientHandle===null||String(v.client_handle)===C.clientHandle));
const active=candidates.length===1?candidates[0][0]:null;
if(active!==s.active){if(busy())abort('ACTIVE SLICE CHANGED OR AMBIGUOUS');s.active=active;s.band=null;s.candidate=null;report(active===null?'WAITING FOR UNAMBIGUOUS ACTIVE SLICE':'ACTIVE SLICE BASELINE; no calibration');}
const band=actualBand();
if(band!==null&&s.active!==null){if(s.band===null){s.band=band;report('INITIAL BAND BASELINE');}
 else if(band!==s.band){if(!s.candidate||s.candidate.band!==band)s.candidate={band,at:now};if(now-s.candidate.at>=C.bandDebounceMs){s.band=band;s.candidate=null;if(s.manual)abort('BAND CHANGED DURING SINGLE CALIBRATION');else if(s.auto)begin('CONFIRMED RADIO BAND CHANGE');else report('BAND CHANGE; AUTO OFF');}}else s.candidate=null;}
if(topic==='control/auto'){if(p===true&&!s.auto){s.auto=true;move('IDLE','AUTO ON; next band change or Calibrate');}else if(p!==true){s.manual=null;s.auto=false;s.pending=null;s.run=null;s.samples=null;s.phase=null;move('IDLE','AUTO OFF; no further AGC-T changes');}}
if(topic==='control/start100'){
 if(busy())report('CALIBRATION ALREADY RUNNING');
 else if(s.active===null||s.band===null||s.candidate||s.rx!=='RX'||now-s.rxAt>C.rxFreshMs||!freshMeters()||!atQuiet()||!s.settingsLoaded||s.settingsError||!['slow','med','fast'].includes(a().agc_mode))report('START BLOCKED; CHECK RX, QUIET FREQUENCY AND LIVE METERS');
 else {s.manual={autoBefore:s.auto};s.auto=true;begin('EXPLICIT SINGLE CALIBRATION FROM AGC-T 100',100);}
}
if(topic==='control/calibrate'){if(!s.auto)report('AUTO OFF; calibration ignored');else if(busy())report('CALIBRATION ALREADY RUNNING');else if(s.active===null||s.band===null)abort('ACTIVE SLICE / RADIO BAND UNKNOWN');else if(!s.settingsLoaded||s.settingsError)report('SETTINGS NOT READY');else begin('EXPLICIT CALIBRATION');}
const mm=topic.match(/^SLC\/(\d+)\/(LEVEL|AGC\+)$/i);
if(mm&&object(p)&&numeric(p.value)){const id=String(Number(mm[1])),name=mm[2].toUpperCase(),supplied=p.unit??s.inventory['SLC/'+id+'/'+name]?.unit;
 const unit=String(supplied).toLowerCase()==='dbm'?'dBm':supplied??null;(s.meters[id]||={})[name]={value:Number(p.value),unit,at:now};
 if(s.samples&&s.phase==='MEASURE'&&id===s.active&&unit==='dBm'&&s.rx==='RX'){if(s.samples[name].length<5000)s.samples[name].push(Number(p.value));else abort('METER SAMPLE LIMIT EXCEEDED');}}
if(s.run&&['MEASURE_NOISE','SCAN_AGCT','KNEE_FOUND','APPLY'].includes(s.state)){
 const r=s.run,actual=Number(a().agc_threshold),expected=s.pending?[s.pending.previous,s.pending.value]:[r.current];
 if(s.rx!=='RX')abort('RX LOST');
 else if(s.active!==r.slice||band!==r.band||Number(a().RF_frequency)!==r.frequency||a().agc_mode!==r.mode||signature()!==r.signature||!expected.includes(actual))abort('SLICE / BAND / FREQUENCY / AGC / RECEIVE SETTINGS CHANGED');
 else if(now-r.started>C.maxRunMs)abort('CALIBRATION TIMEOUT');
 else if(scanning()&&(!freshMeters()||now-s.rxAt>C.rxFreshMs||!atQuiet()))abort('SCAN TELEMETRY STALE OR QUIET FREQUENCY LOST');
}
if(s.pending){if(now-s.pending.at>C.ackTimeoutMs)abort('AGC-T ACKNOWLEDGEMENT / READBACK TIMEOUT');else if(s.pending.ack&&s.pending.seen){const pending=s.pending;s.pending=null;s.run.current=pending.value;
 if(pending.purpose==='apply'){s.final=pending.value;s.phase=null;s.samples=null;finishManual();move('DONE','AGC-T APPLIED AND CONFIRMED; no continuous regulation');}
 else{s.phase='SETTLE';s.settleUntil=now+C.settleMs;s.samples=null;report('SCAN_AGCT; AGC settling');}}}
if(s.state==='BAND_CHANGE')move('WAIT_RX','WAITING FOR RX; no immediate AGC-T change');
else if(s.state==='WAIT_RX'){
 if(now-s.since>C.timeoutMs)abort('RX / BAND / LIVE STATUS TIMEOUT');
 else if(s.rx==='RX'&&now-s.rxAt<=C.rxFreshMs&&!s.candidate&&band===s.band&&numeric(a().RF_frequency)&&threshold(Number(a().agc_threshold))&&['slow','med','fast'].includes(a().agc_mode)){
  s.run={slice:s.active,band:s.band,started:now,frequency:Number(a().RF_frequency),initial:Number(a().agc_threshold),current:Number(a().agc_threshold),scanStart:s.run.scanStart,mode:a().agc_mode,signature:signature(),plateau:false,confirming:false};
  newWindow();move('MEASURE_NOISE','COLLECTING LIVE LEVEL AND AGC+; no radio changes');}
}else if(s.state==='MEASURE_NOISE'&&now-s.windowAt>=C.measureMs){const values=stats();if(values&&freshMeters()){
 s.result={...values,at:now,quietFrequencyMHz:quiet(),noiseFloorConfirmed:false};s.run.baseline=values;s.run.reference=values;s.samples=null;report('LIVE MEASUREMENT COMPLETE');
 if(quiet()===null)abort('NO QUIET FREQUENCY CONFIGURED');else if(!atQuiet())abort('TUNE TO CONFIGURED QUIET FREQUENCY');
 else if(Object.values(values).some(v=>v.spread>C.maxSpreadDb))abort('UNSTABLE SIGNAL; NO SCAN');
 else{move('SCAN_AGCT','NOISE BASELINE ACCEPTED; starting downward scan');if(s.run.scanStart!==null&&s.run.scanStart!==s.run.current){s.run.rebaseline=true;sendThreshold(s.run.scanStart,'start');}else descend();}
 }else if(now-s.windowAt>C.timeoutMs)abort('MISSING / STALE / WRONG-UNIT LIVE METERS');
}else if(s.state==='SCAN_AGCT'&&!s.pending){
 if(s.phase==='SETTLE'&&now>=s.settleUntil)newWindow();
 else if(s.phase==='MEASURE'&&now-s.windowAt>=C.measureMs){const values=stats();if(!values){if(now-s.windowAt>C.timeoutMs)abort('NOT ENOUGH LIVE SCAN SAMPLES');}
 else{const r=s.run,level=values.LEVEL,agc=values['AGC+'];s.trace.push({threshold:r.current,...values,at:now});s.samples=null;
  if(Object.values(values).some(v=>v.spread>C.maxSpreadDb)||Math.abs(level.median-r.baseline.LEVEL.median)>C.maxInputDriftDb)abort('RECEIVED SIGNAL / INPUT NOISE CHANGED; ABORTED');
  else if(r.rebaseline){r.rebaseline=false;r.reference=values;descend();}
  else{const drop=r.reference['AGC+'].median-agc.median;
   if(r.confirming){if(drop>=C.kneeDropDb&&Math.abs(agc.median-r.candidateAgc)<=C.plateauDb){s.knee=r.current;s.final=Math.max(C.minThreshold,Math.min(100,s.knee+C.kneeOffset));s.phase=null;move('KNEE_FOUND','KNEE CONFIRMED IN TWO WINDOWS WITH STABLE LEVEL');}else abort('KNEE NOT REPRODUCIBLE');}
   else if(drop>=C.kneeDropDb){if(!r.plateau)abort('NO PRECEDING AGC PLATEAU; CHOOSE A HIGHER EXPLICIT SCAN START');else{r.confirming=true;r.candidateAgc=agc.median;newWindow();report('CONFIRMING KNEE; second independent measurement window');}}
   else if(drop < -C.plateauDb)abort('AGC OUTPUT INCREASED; SIGNAL NOT STABLE');
   else{if(Math.abs(drop)<=C.plateauDb){r.plateau=true;r.reference=values;}descend();}
  }
 }
 }
}else if(s.state==='KNEE_FOUND'){move('APPLY','SETTING FINAL AGC-T ONCE');sendThreshold(s.final,'apply');}
if(topic==='clock'){
 if(!s.lastInventory||now-s.lastInventory>=60000){s.lastInventory=now;for(const cmd of ['sub client all','sub slice all','sub tx all','sub pan all','meter list'])read(cmd);}
 if(!s.lastTxSub||now-s.lastTxSub>=5000){s.lastTxSub=now;read('sub tx all');}report();
}
flow.set('agctWritePermit',s.pending&&scanning()&&s.auto&&s.rx==='RX'&&now-s.rxAt<=C.rxFreshMs&&freshMeters()&&atQuiet()&&!s.settingsError?{
 command:s.pending.command,token:s.pending.token,epoch:s.epoch,expires:Math.min(now+1000,s.pending.at+C.ackTimeoutMs)}:null);
context.set('watcher',s);
node.status({fill:s.state==='ERROR'?'red':s.state==='DONE'?'green':s.auto?'blue':'grey',shape:'dot',text:s.state+': '+s.reason});
return [out.length?out:null,commands.length?commands:null,saves.length?saves:null];

if(msg.action || typeof msg.payload!=='string'){node.error('Blocked invalid command',msg);return null;}
if(/^(meter list|sub (client|slice|tx|pan) all|sub meter \d+)$/.test(msg.payload))return {payload:msg.payload,_agctReadEpoch:msg._agctReadEpoch};
const match=msg.payload.match(/^slice s (\d+) agc_threshold=(\d{1,3})$/);
const permit=flow.get('agctWritePermit'),tag=msg._agctWrite;
const key=tag?tag.epoch+':'+tag.token:null;
if(match && Number(match[2])<=100 && permit && tag && permit.command===msg.payload && permit.token===tag.token && permit.epoch===tag.epoch && Date.now()<=permit.expires && context.get('lastSent')!==key){
 context.set('lastSent',key);flow.set('agctWritePermit',null);
 return {payload:msg.payload,_agctWrite:tag};
}
node.error('Blocked AGC-T write: no current RX/scan permit',msg);return null;

const h=msg.req?.headers||{},body=msg.payload,action=body?.action;
const originOK=typeof h.host==='string'&&['http://'+h.host,'https://'+h.host].includes(h.origin);
msg.headers={'Content-Type':'application/json','Cache-Control':'no-store'};
function reject(code,error){msg.statusCode=code;msg.payload={error};return [null,msg];}
if(!originOK||h['x-agct-watcher']!=='1'||!/^application\/json(?:;|$)/i.test(h['content-type']||'')||!['on','off','calibrate','settings','start100'].includes(action))return reject(400,'Ungültige Watcher-Anforderung');
const status=flow.get('agctUiStatus');
if(action!=='off'&&(!status||Date.now()-status.at>5000))return reject(409,'Keine aktuellen Watcher-Daten');
