let command;
if(action==='settings'){
 if(running)return reject(409,'Zuerst Auto AUS wählen');
 const v = body.settings ?? { band: body.band, quietMHz: body.quietMHz, scanStart: body.scanStart };
 if(!v||typeof v.band!=='string'||!/^[A-Za-z0-9_-]{1,16}$/.test(v.band)||['__proto__','constructor'].includes(v.band)||
 !(v.quietMHz===null||(typeof v.quietMHz==='number'&&Number.isFinite(v.quietMHz)&&v.quietMHz>0&&v.quietMHz<=100000))||
 !(v.scanStart===null||(Number.isInteger(v.scanStart)&&v.scanStart>=0&&v.scanStart<=100)))return reject(400,'Band, Frequenz oder AGC-T-Startwert ungültig');
 if(v.band!==status.band && !Object.hasOwn(status.settings?.quietMHzByBand||{},v.band))return reject(400,'Unbekanntes Band');
