 const freshMeters=['LEVEL','AGC+'].every(name=>{const m=status.meters?.[name];return m&&m.unit==='dBm'&&Number.isFinite(m.value)&&Date.now()-m.at<=3000;});
 if(running||status.rxTx!=='RX'||status.activeSlice==null||status.band==null||!status.settingsLoaded||status.settingsError||!freshMeters||!['slow','med','fast'].includes(status.agcMode)||typeof quiet!=='number'||typeof status.frequencyMHz!=='number'||Math.abs(quiet-status.frequencyMHz)>0.000001)return reject(409,'Bitte Mess-QRG übernehmen, darauf abstimmen und auf RX mit aktuellen Metern warten');
